for (const [p, texto] of Object.entries(FICHEROS)) {
  const actual = fs.existsSync(p) ? fs.readFileSync(p, 'utf8') : null
  if (actual !== null && actual.replace(/\r\n/g, '\n') === texto) { console.log('· ' + p + ' ya estaba'); continue }
  fs.mkdirSync(path.dirname(p), { recursive: true })
  const crlf = actual !== null && actual.includes('\r\n')
  fs.writeFileSync(p, crlf ? texto.replace(/\n/g, '\r\n') : texto)
  console.log('✓ ' + p)
}
